import { addCornerControl, IconButton, toast } from "march/ui"
import { helpCircle } from "march/icons"

// yardım balonu: sayfanın alt-son köşesine yuvarlak bir düğme ekler; bileşen gidince düğme de kalkar
export function HelpBubble() {
  addCornerControl("bottom-end", <IconButton icon={helpCircle} label="Yardım" variant="solid" shape="round" on:click={() => toast("Size nasıl yardım edebiliriz?")} /> as Node, 5)
  return <p sx={{ text: "sm", color: "muted" }}>Sağ alt köşedeki yardım düğmesine bakın.</p>
}

import { addCornerControl, Button, Segmented } from "march/ui"

// geri bildirim düğmesi: köşe seçilir, düğme oraya taşınır; eski köşeden çıkar
export function FeedbackCorner() {
  let $corner = "bottom-start"
  let off = () => {}
  const place = (c: string) => { off(); off = addCornerControl(c as "bottom-start", <Button size="sm" variant="primary">Geri bildirim</Button> as Node, 1); $corner = c }
  place("bottom-start")
  return <div sx={{ flex: "col", gap: 2 }}>
    <Segmented label="Köşe" value={$corner} options={["top-start", "top-end", "bottom-start", "bottom-end"]} onChange={place} />
    <span sx={{ text: "sm", color: "muted" }}>Düğme şimdi {$corner} köşesinde</span>
  </div>
}

import { BottomRightControls, CornerControls, addCornerControl, addBottomRightControl, Button } from "march/ui"

// köşe API'sinin hepsi: BottomRightControls (label, class), CornerControls (corner), addCornerControl (sıra: order),
// addBottomRightControl ve geri dönen off()
export function BottomRightControlsLab() {
  let $count = 0
  const offs: (() => void)[] = []
  const add = () => { $count++; offs.push(addBottomRightControl(<Button size="sm">{`Denetim ${$count}`}</Button> as Node, $count)) }
  const clear = () => { offs.splice(0).forEach((off) => off()); $count = 0 }
  addCornerControl("top-start", <span class="lab-top">Üst baş</span> as Node)
  return <div sx={{ flex: "col", gap: 2 }}>
    <BottomRightControls label="Sayfa denetimleri" class="lab-corner" />
    <CornerControls corner="top-start" label="Üst baş köşesi" />
    <div sx={{ flex: "row", gap: 2 }}>
      <Button size="sm" on:click={add}>Köşeye ekle</Button>
      <Button size="sm" on:click={clear}>Hepsini çıkar</Button>
    </div>
    <span class="lab-count">{$count} denetim</span>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { BottomRightControlsLab } from "./BottomRightControlsLab.tsx"

// BottomRightControlsLab'in testleri: kaydedince Testler sekmesinde çalışır
test("köşe kendi adıyla çizilir", () => {
  const s = renderTest(() => <BottomRightControlsLab />)
  expect(s.get(".lab-corner")?.getAttribute("aria-label")).toBe("Sayfa denetimleri")
})

test("eklenen denetim köşeye girer, off() çıkarır", async () => {
  const s = renderTest(() => <BottomRightControlsLab />)
  await s.click("Köşeye ekle")
  await s.click("Köşeye ekle")
  // the bottom-end corner is one for the page: it may sit outside the test's box
  const corner = () => document.querySelector(".m-corner-bottom-end, .lab-corner")?.textContent ?? ""
  expect(s.get(".lab-count")?.textContent).toBe("2 denetim")
  expect(document.body.textContent).toContain("Denetim 2")
  await s.click("Hepsini çıkar")
  expect(s.get(".lab-count")?.textContent).toBe("0 denetim")
  expect(corner()).not.toContain("Denetim 1")
})
